// src/pages/MensClothing.js
import React from 'react';

const MensClothing = () => {
    return (
        <div className="container mt-5 text-center mt-4 m-auto mb-4 h-100">


            <div className="row">
                <div className="col-md-4">
                    <div className="card">
                        <img src="your-image-url.jpg" alt="Men's Shirt" className="card-img-top" />
                        <div className="card-body">
                            <h5 className="card-title">Áo sơ mi nam</h5>
                            <p className="card-text">Chất liệu vải thoáng mát, kiểu dáng thời trang.</p>
                        </div>
                    </div>
                </div>
                <div className="col-md-4">
                    <div className="card">
                        <img src="your-image-url.jpg" alt="Men's Jeans" className="card-img-top" />
                        <div className="card-body">
                            <h5 className="card-title">Quần Jeans nam</h5>
                            <p className="card-text">Quần jeans với chất liệu bền và thiết kế đa dạng.</p>
                        </div>
                    </div>
                </div>
                {/* Add more items as needed */}
            </div>
        </div>
    );
};

export default MensClothing;
